import json

def solve_puzzle():
    houses = [1, 2, 3, 4]

    names = ['Eric', 'Alice', 'Peter', 'Arnold']
    hairs = ['blonde', 'black', 'red', 'brown']
    sports = ['swimming', 'soccer', 'basketball', 'tennis']

    solutions = []

    for p_red in houses:
        # Clue 7: The person who has red hair is directly left of the person who has black hair.
        if p_red >= 4:
            continue
        p_black = p_red + 1

        # Hair positions: ensure all unique
        for p_blonde in houses:
            if p_blonde in (p_red, p_black):
                continue
            # Remaining hair (brown) will be the last remaining house
            remaining_hairs_houses = [h for h in houses if h not in (p_red, p_black, p_blonde)]
            if len(remaining_hairs_houses) != 1:
                continue
            p_brown = remaining_hairs_houses[0]

            # Sports: Clue 4: black hair = tennis
            p_tennis = p_black

            for p_soccer in houses:
                # Clue 1: soccer is not in the second house
                if p_soccer == 2:
                    continue
                if p_soccer == p_tennis:
                    continue

                for p_swimming in houses:
                    if p_swimming in (p_tennis, p_soccer):
                        continue

                    # Determine basketball position as the remaining one
                    remaining_sport_houses = [h for h in houses if h not in (p_tennis, p_soccer, p_swimming)]
                    if len(remaining_sport_houses) != 1:
                        continue
                    p_basketball = remaining_sport_houses[0]

                    # Clue 3: blonde is somewhere to the right of basketball
                    if not (p_blonde > p_basketball):
                        continue

                    # Names:
                    # Clue 2: Eric is the person who has blonde hair
                    p_eric = p_blonde

                    # Clue 6: Alice is the person who loves swimming
                    p_alice = p_swimming

                    # Clue 5: Arnold is somewhere to the left of the person who has red hair
                    for p_arnold in houses:
                        if p_arnold in (p_eric, p_alice):
                            continue
                        if not (p_arnold < p_red):
                            continue
                        # Peter takes the remaining house
                        remaining_name_houses = [h for h in houses if h not in (p_eric, p_alice, p_arnold)]
                        if len(remaining_name_houses) != 1:
                            continue
                        p_peter = remaining_name_houses[0]

                        # Build mappings by house
                        name_by_house = {
                            p_eric: 'Eric',
                            p_alice: 'Alice',
                            p_peter: 'Peter',
                            p_arnold: 'Arnold'
                        }
                        hair_by_house = {
                            p_blonde: 'blonde',
                            p_black: 'black',
                            p_red: 'red',
                            p_brown: 'brown'
                        }
                        sport_by_house = {
                            p_swimming: 'swimming',
                            p_soccer: 'soccer',
                            p_basketball: 'basketball',
                            p_tennis: 'tennis'
                        }

                        # Collect solution
                        solutions.append((name_by_house, hair_by_house, sport_by_house))

    # Take the first solution (the puzzle should yield a unique solution)
    if not solutions:
        raise RuntimeError("No solution found")

    name_by_house, hair_by_house, sport_by_house = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Hair", "Sport"],
            "rows": []
        }
    }

    for h in sorted([1, 2, 3, 4]):
        row = [
            str(h),
            name_by_house[h],
            hair_by_house[h],
            sport_by_house[h]
        ]
        result["solution"]["rows"].append(row)

    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve_puzzle()
